                         "frente":  "Por que o pai nunca é \u0027portador silencioso\u0027 de uma condição recessiva ligada ao X?",
                         "verso":  "Porque o homem tem só um X: se ele carrega o alelo recessivo, ele manifesta a condição — não existe heterozigose no sexo com um único X. É por isso que filhas de pai daltônico são obrigatoriamente portadoras, nunca só \u0027talvez\u0027."
