                       "verso":  "A imagem fica a 2,0 m ATRÁS do espelho, tão distante dele quanto o objeto está na frente. A distância pessoa–imagem é a SOMA das duas distâncias ao espelho (4,0 m), não a diferença — confundir as duas é o erro clássico."
