                       "verso":  "v = 1,0 m/s, pela conservação da quantidade de movimento: 2,0×3,0 = (2,0+4,0)×v. A energia cinética NÃO se conserva numa colisão perfeitamente inelástica — parte se converte em deformação e calor."
