                       "frente":  "Pelo princípio de Pascal, uma prensa hidráulica com áreas de 20 cm² e 500 cm² recebe 40 N no pistão menor. Qual a força no maior, e a prensa \u0027cria\u0027 energia?",
                       "verso":  "1.000 N (força multiplicada por 25, na razão das áreas). Não há criação de energia: o deslocamento do êmbolo maior é 25 vezes MENOR que o do menor — o trabalho se conserva, só a força é redistribuída."
