                       "frente":  "Por que esquis distribuem o peso de uma pessoa sobre a neve sem que ela afunde, mesmo que o peso não mude?",
                       "verso":  "O peso é o mesmo, mas a área de contato aumenta muito, e pressão é força dividida por área. Com vinte vezes mais área, a pressão cai a um vigésimo. A força de atrito, aliás, não depende da área de contato — só do coeficiente e da força normal."
