                       "verso":  "Em paralelo. Em série as resistências se somam, a corrente total cai, e a potência dissipada em cada lâmpada diminui. Em paralelo cada lâmpada recebe a tensão plena da fonte. A corrente é a mesma em todos os pontos de um circuito em série — não é \u0027consumida\u0027 ao longo do caminho."
